UPDATE grammar SET examples = '[{"jp": "<ruby>一緒<rp>(</rp><rt>いっしょ</rt><rp>)</rp></ruby>に<ruby>帰<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>りましょう。", "ko": "함께 돌아갑시다."}, {"jp": "<ruby>少<rp>(</rp><rt>すこ</rt><rp>)</rp></ruby>し<ruby>休<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>みましょう。", "ko": "조금 쉽시다."}]'::jsonb WHERE (examples->0->>'ko') = '함께 돌아갑시다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>今<rp>(</rp><rt>こん</rt><rp>)</rp></ruby><ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>しています。", "ko": "지금 공부하고 있습니다."}, {"jp": "テレビを<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>ています。", "ko": "TV를 보고 있습니다."}]'::jsonb WHERE (examples->0->>'ko') = '지금 공부하고 있습니다.';
UPDATE grammar SET examples = '[{"jp": "はやく<ruby>来<rp>(</rp><rt>き</rt><rp>)</rp></ruby>てください。", "ko": "빨리 오세요."}, {"jp": "すぐに<ruby>終<rp>(</rp><rt>お</rt><rp>)</rp></ruby>わります。", "ko": "금방 끝납니다."}]'::jsonb WHERE (examples->0->>'ko') = '빨리 오세요.';
UPDATE grammar SET examples = '[{"jp": "シャツが<ruby>五<rp>(</rp><rt>ご</rt><rp>)</rp></ruby><ruby>枚<rp>(</rp><rt>まい</rt><rp>)</rp></ruby>あります。", "ko": "셔츠가 다섯 장 있습니다."}, {"jp": "<ruby>切符<rp>(</rp><rt>きっぷ</rt><rp>)</rp></ruby>を<ruby>二<rp>(</rp><rt>に</rt><rp>)</rp></ruby><ruby>枚<rp>(</rp><rt>まい</rt><rp>)</rp></ruby><ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>いました。", "ko": "표를 두 장 샀습니다."}]'::jsonb WHERE (examples->0->>'ko') = '셔츠가 다섯 장 있습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>五<rp>(</rp><rt>ご</rt><rp>)</rp></ruby><ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>ごろに<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きます。", "ko": "5시쯤에 갑니다."}, {"jp": "<ruby>夜<rp>(</rp><rt>よる</rt><rp>)</rp></ruby><ruby>十<rp>(</rp><rt>じゅう</rt><rp>)</rp></ruby><ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>ごろ<ruby>寝<rp>(</rp><rt>ね</rt><rp>)</rp></ruby>ます。", "ko": "밤 10시쯤 잡니다."}]'::jsonb WHERE (examples->0->>'ko') = '5시쯤에 갑니다.';
UPDATE grammar SET examples = '[{"jp": "よく<ruby>映画<rp>(</rp><rt>えいが</rt><rp>)</rp></ruby>を<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>ます。", "ko": "자주 영화를 봅니다."}, {"jp": "よく<ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>しましたね。", "ko": "공부 열심히 하셨네요."}]'::jsonb WHERE (examples->0->>'ko') = '자주 영화를 봅니다.';
UPDATE grammar SET examples = '[{"jp": "たぶん<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>は<ruby>雨<rp>(</rp><rt>あめ</rt><rp>)</rp></ruby>でしょう。", "ko": "아마 내일은 비가 오겠지요."}, {"jp": "<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>はたぶん<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>るでしょう。", "ko": "그는 아마 오겠지요."}]'::jsonb WHERE (examples->0->>'ko') = '아마 내일은 비가 오겠지요.';
UPDATE grammar SET examples = '[{"jp": "<ruby>入<rp>(</rp><rt>はい</rt><rp>)</rp></ruby>ってもいいです。", "ko": "들어와도 좋습니다."}, {"jp": "<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べてもいいです。", "ko": "먹어도 좋습니다."}]'::jsonb WHERE (examples->0->>'ko') = '들어와도 좋습니다.';
UPDATE grammar SET examples = '[{"jp": "9<ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>から5<ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>まで。", "ko": "9시부터 5시까지."}, {"jp": "ここから<ruby>駅<rp>(</rp><rt>えき</rt><rp>)</rp></ruby>まで。", "ko": "여기서 역까지."}]'::jsonb WHERE (examples->0->>'ko') = '9시부터 5시까지.';
UPDATE grammar SET examples = '[{"jp": "<ruby>寿司<rp>(</rp><rt>すし</rt><rp>)</rp></ruby>を<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べたいです。", "ko": "초밥을 먹고 싶습니다."}, {"jp": "<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きたいです。", "ko": "일본에 가고 싶습니다."}]'::jsonb WHERE (examples->0->>'ko') = '초밥을 먹고 싶습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>一緒<rp>(</rp><rt>いっしょ</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きましょうか。", "ko": "함께 갈까요?"}, {"jp": "<ruby>手伝<rp>(</rp><rt>てつだ</rt><rp>)</rp></ruby>いましょうか。", "ko": "도와드릴까요?"}]'::jsonb WHERE (examples->0->>'ko') = '함께 갈까요?';
UPDATE grammar SET examples = '[{"jp": "タバコが<ruby>嫌<rp>(</rp><rt>きら</rt><rp>)</rp></ruby>いです。", "ko": "담배를 싫어합니다."}, {"jp": "<ruby>寒<rp>(</rp><rt>さむ</rt><rp>)</rp></ruby>いのが<ruby>嫌<rp>(</rp><rt>きら</rt><rp>)</rp></ruby>いです。", "ko": "추운 것을 싫어합니다."}]'::jsonb WHERE (examples->0->>'ko') = '담배를 싫어합니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>音楽<rp>(</rp><rt>おんがく</rt><rp>)</rp></ruby>を<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>きながら<ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>します。", "ko": "음악을 들으면서 공부합니다."}, {"jp": "<ruby>歩<rp>(</rp><rt>ある</rt><rp>)</rp></ruby>きながら<ruby>話<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>しましょう。", "ko": "걸으면서 이야기합시다."}]'::jsonb WHERE (examples->0->>'ko') = '음악을 들으면서 공부합니다.';
UPDATE grammar SET examples = '[{"jp": "これはいくらですか?", "ko": "이것은 얼마ですか?"}, {"jp": "<ruby>全部<rp>(</rp><rt>ぜんぶ</rt><rp>)</rp></ruby>でいくらです?", "ko": "전부 얼마ですか?"}]'::jsonb WHERE (examples->0->>'ko') = '이것은 얼마ですか?';
UPDATE grammar SET examples = '[{"jp": "<ruby>歌<rp>(</rp><rt>か</rt><rp>)</rp></ruby>を<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>くのが<ruby>好<rp>(</rp><rt>す</rt><rp>)</rp></ruby>きです。", "ko": "노래를 듣는 것을 좋아합니다."}, {"jp": "<ruby>絵<rp>(</rp><rt>え</rt><rp>)</rp></ruby>を<ruby>描<rp>(</rp><rt>えが</rt><rp>)</rp></ruby>くことは<ruby>楽<rp>(</rp><rt>たの</rt><rp>)</rp></ruby>しいです。", "ko": "그림을 그리는 것은 즐겁습니다."}]'::jsonb WHERE (examples->0->>'ko') = '노래를 듣는 것을 좋아합니다.';
UPDATE grammar SET examples = '[{"jp": "ぜひうちへ<ruby>来<rp>(</rp><rt>き</rt><rp>)</rp></ruby>てください。", "ko": "꼭 저희 집에 놀러 오세요."}, {"jp": "ぜひ<ruby>読<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>んでください。", "ko": "꼭 읽어 보세요."}]'::jsonb WHERE (examples->0->>'ko') = '꼭 저희 집에 놀러 오세요.';
UPDATE grammar SET examples = '[{"jp": "<ruby>全然<rp>(</rp><rt>ぜんぜん</rt><rp>)</rp></ruby>わかりません。", "ko": "전혀 모르겠습니다."}, {"jp": "<ruby>全然<rp>(</rp><rt>ぜんぜん</rt><rp>)</rp></ruby><ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べませんでした。", "ko": "전혀 먹지 않았습니다."}]'::jsonb WHERE (examples->0->>'ko') = '전혀 모르겠습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby>より<ruby>暑<rp>(</rp><rt>あつ</rt><rp>)</rp></ruby>いです。", "ko": "어제보다 덥습니다."}, {"jp": "<ruby>飛行機<rp>(</rp><rt>ひこうき</rt><rp>)</rp></ruby>のほうが<ruby>新幹線<rp>(</rp><rt>しんかんせん</rt><rp>)</rp></ruby>より<ruby>速<rp>(</rp><rt>はや</rt><rp>)</rp></ruby>いです。", "ko": "비행기가 신칸센보다 빠릅니다."}]'::jsonb WHERE (examples->0->>'ko') = '어제보다 덥습니다.';
UPDATE grammar SET examples = '[{"jp": "リンゴが<ruby>好<rp>(</rp><rt>す</rt><rp>)</rp></ruby>きです。", "ko": "사과를 좋아합니다."}, {"jp": "<ruby>旅行<rp>(</rp><rt>りょこう</rt><rp>)</rp></ruby>が<ruby>好<rp>(</rp><rt>す</rt><rp>)</rp></ruby>きです。", "ko": "여행을 좋아합니다."}]'::jsonb WHERE (examples->0->>'ko') = '사과를 좋아합니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>水<rp>(</rp><rt>すい</rt><rp>)</rp></ruby>をください。", "ko": "물 주세요."}, {"jp": "これをください。", "ko": "이것을 주세요."}]'::jsonb WHERE (examples->0->>'ko') = '물 주세요.';
UPDATE grammar SET examples = '[{"jp": "なかなかバスが<ruby>来<rp>(</rp><rt>き</rt><rp>)</rp></ruby>ません。", "ko": "좀처럼 버스가 오지 않습니다."}, {"jp": "なかなか<ruby>覚<rp>(</rp><rt>おぼ</rt><rp>)</rp></ruby>えられません。", "ko": "좀처럼 외워지지 않습니다."}]'::jsonb WHERE (examples->0->>'ko') = '좀처럼 버스가 오지 않습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きたいです。しかし、お<ruby>金<rp>(</rp><rt>かね</rt><rp>)</rp></ruby>がありません。", "ko": "가고 싶습니다. 하지만 돈이 없습니다."}, {"jp": "<ruby>雨<rp>(</rp><rt>う</rt><rp>)</rp></ruby>が<ruby>降<rp>(</rp><rt>お</rt><rp>)</rp></ruby>りました。しかし、<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きます.", "ko": "비가 왔습니다. 하지만 갑니다."}]'::jsonb WHERE (examples->0->>'ko') = '가고 싶습니다. 하지만 돈이 없습니다.';
UPDATE grammar SET examples = '[{"jp": "ゆっくり<ruby>話<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>してください。", "ko": "천천히 말씀해 주세요."}, {"jp": "だんだん<ruby>暖<rp>(</rp><rt>あたた</rt><rp>)</rp></ruby>かくなります。", "ko": "점점 따뜻해집니다."}]'::jsonb WHERE (examples->0->>'ko') = '천천히 말씀해 주세요.';
UPDATE grammar SET examples = '[{"jp": "トイレはどこですか?", "ko": "화장실은 어디ですか?"}, {"jp": "あの<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>は<ruby>誰<rp>(</rp><rt>だれ</rt><rp>)</rp></ruby>です?", "ko": "저 사람은 누구ですか?"}]'::jsonb WHERE (examples->0->>'ko') = '화장실은 어디ですか?';
UPDATE grammar SET examples = '[{"jp": "<ruby>決<rp>(</rp><rt>けっ</rt><rp>)</rp></ruby>してあきらめません。", "ko": "결코 포기하지 않겠습니다."}, {"jp": "<ruby>決<rp>(</rp><rt>けっ</rt><rp>)</rp></ruby>して<ruby>嘘<rp>(</rp><rt>うそ</rt><rp>)</rp></ruby>を<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>いません。", "ko": "결코 거짓말을 하지 않겠습니다."}]'::jsonb WHERE (examples->0->>'ko') = '결코 포기하지 않겠습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby><ruby>早<rp>(</rp><rt>はや</rt><rp>)</rp></ruby>く<ruby>起<rp>(</rp><rt>お</rt><rp>)</rp></ruby>きるつもりです。", "ko": "내일 일찍 일어날 작정です."}, {"jp": "<ruby>夏休<rp>(</rp><rt>なつやす</rt><rp>)</rp></ruby>みは<ruby>旅行<rp>(</rp><rt>りょこう</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>くつもりです。", "ko": "여름방학에는 여행을 갈 작정です."}]'::jsonb WHERE (examples->0->>'ko') = '내일 일찍 일어날 작정です.';
UPDATE grammar SET examples = '[{"jp": "<ruby>寝<rp>(</rp><rt>ね</rt><rp>)</rp></ruby>る<ruby>前<rp>(</rp><rt>まえ</rt><rp>)</rp></ruby>に<ruby>薬<rp>(</rp><rt>くすり</rt><rp>)</rp></ruby>を<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>みます。", "ko": "자기 전에 약을 먹습니다."}, {"jp": "<ruby>食事<rp>(</rp><rt>しょくじ</rt><rp>)</rp></ruby>の<ruby>前<rp>(</rp><rt>まえ</rt><rp>)</rp></ruby>に<ruby>手<rp>(</rp><rt>て</rt><rp>)</rp></ruby>を<ruby>洗<rp>(</rp><rt>あら</rt><rp>)</rp></ruby>います。", "ko": "식사 전에 손을 씻습니다."}]'::jsonb WHERE (examples->0->>'ko') = '자기 전에 약을 먹습니다.';
UPDATE grammar SET examples = '[{"jp": "まず<ruby>顔<rp>(</rp><rt>かお</rt><rp>)</rp></ruby>を<ruby>洗<rp>(</rp><rt>あら</rt><rp>)</rp></ruby>います。", "ko": "먼저 세수를 합니다."}, {"jp": "まずこれを<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>てください。", "ko": "우선 이것을 보세요."}]'::jsonb WHERE (examples->0->>'ko') = '먼저 세수를 합니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>を<ruby>話<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>すことができます。", "ko": "일본어를 말할 수 있습니다."}, {"jp": "ピアノを<ruby>弾<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>くことができます。", "ko": "피아노를 칠 수 있습니다."}]'::jsonb WHERE (examples->0->>'ko') = '일본어를 말할 수 있습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>子供<rp>(</rp><rt>こども</rt><rp>)</rp></ruby>みたいな<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>です。", "ko": "아이 같은 사람です."}, {"jp": "<ruby>雪<rp>(</rp><rt>ゆき</rt><rp>)</rp></ruby>みたいに<ruby>白<rp>(</rp><rt>しろ</rt><rp>)</rp></ruby>いです。", "ko": "눈처럼 하얗습니다."}]'::jsonb WHERE (examples->0->>'ko') = '아이 같은 사람です.';
UPDATE grammar SET examples = '[{"jp": "<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ったことがあります。", "ko": "일본에 간 적이 있습니다."}, {"jp": "<ruby>納豆<rp>(</rp><rt>なっとう</rt><rp>)</rp></ruby>を<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べたことがあります。", "ko": "낫또를 먹은 적이 있습니다."}]'::jsonb WHERE (examples->0->>'ko') = '일본에 간 적이 있습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>寒<rp>(</rp><rt>さむ</rt><rp>)</rp></ruby>くなりました。", "ko": "추워졌습니다."}, {"jp": "<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>が<ruby>上手<rp>(</rp><rt>じょうず</rt><rp>)</rp></ruby>になりました。", "ko": "일본어를 잘하게 되었습니다."}]'::jsonb WHERE (examples->0->>'ko') = '추워졌습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>少々<rp>(</rp><rt>しょうしょう</rt><rp>)</rp></ruby>お<ruby>待<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>ちくださいませ。", "ko": "잠시 기다려 주십시오."}, {"jp": "どうぞお<ruby>入<rp>(</rp><rt>い</rt><rp>)</rp></ruby>りくださいませ。", "ko": "어서 들어오십시오."}]'::jsonb WHERE (examples->0->>'ko') = '잠시 기다려 주십시오.';
UPDATE grammar SET examples = '[{"jp": "ここでタバコを<ruby>吸<rp>(</rp><rt>す</rt><rp>)</rp></ruby>ってはいけません。", "ko": "여기서 담배를 피워서는 안 됩니다."}, {"jp": "テレビを<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>てはいけません。", "ko": "TV를 봐서는 안 됩니다."}]'::jsonb WHERE (examples->0->>'ko') = '여기서 담배를 피워서는 안 됩니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>のあとに<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>みに<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きます。", "ko": "업무 후에 마시러 갑니다."}, {"jp": "<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>いたあとに<ruby>答<rp>(</rp><rt>こた</rt><rp>)</rp></ruby>えてください。", "ko": "들은 후에 대답해 주세요."}]'::jsonb WHERE (examples->0->>'ko') = '업무 후에 마시러 갑니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>は<ruby>二<rp>(</rp><rt>に</rt><rp>)</rp></ruby><ruby>十<rp>(</rp><rt>じゅう</rt><rp>)</rp></ruby><ruby>歳<rp>(</rp><rt>さい</rt><rp>)</rp></ruby>です。", "ko": "저는 스무 살です."}, {"jp": "<ruby>妹<rp>(</rp><rt>いもうと</rt><rp>)</rp></ruby>は<ruby>十<rp>(</rp><rt>じゅう</rt><rp>)</rp></ruby><ruby>歳<rp>(</rp><rt>さい</rt><rp>)</rp></ruby>です。", "ko": "동생은 열 살です."}]'::jsonb WHERE (examples->0->>'ko') = '저는 스무 살です.';
UPDATE grammar SET examples = '[{"jp": "<ruby>勉<rp>(</rp><rt>つとむ</rt><rp>)</rp></ruby><ruby>强<rp>(</rp><rt>强</rt><rp>)</rp></ruby>をしませんでした。それで、<ruby>試験<rp>(</rp><rt>しけん</rt><rp>)</rp></ruby>に<ruby>落<rp>(</rp><rt>お</rt><rp>)</rp></ruby>ちました。", "ko": "공부를 하지 않았습니다. 그래서 시험에 떨어졌습니다."}, {"jp": "<ruby>雨<rp>(</rp><rt>う</rt><rp>)</rp></ruby>でした。それで<ruby>来<rp>(</rp><rt>き</rt><rp>)</rp></ruby>ませんでした。", "ko": "비였습니다. 그래서 오지 않았습니다."}]'::jsonb WHERE (examples->0->>'ko') = '공부를 하지 않았습니다. 그래서 시험에 떨어졌습니다.';
UPDATE grammar SET examples = '[{"jp": "いい<ruby>天気<rp>(</rp><rt>てんき</rt><rp>)</rp></ruby>ですね。ところで、お<ruby>元気<rp>(</rp><rt>げんき</rt><rp>)</rp></ruby>です?", "ko": "좋은 날씨네요. 그런데 잘 지내시나요?"}, {"jp": "<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>が<ruby>上手<rp>(</rp><rt>じょうず</rt><rp>)</rp></ruby>ですね。ところで、どこで<ruby>習<rp>(</rp><rt>なら</rt><rp>)</rp></ruby>いましたか?", "ko": "일본어를 잘하시네요. 그런데 어디서 배우셨나요?"}]'::jsonb WHERE (examples->0->>'ko') = '좋은 날씨네요. 그런데 잘 지내시나요?';
UPDATE grammar SET examples = '[{"jp": "<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>のカバンです。", "ko": "저의 가방です."}, {"jp": "<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>の<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>です。", "ko": "일본어 선생님です."}]'::jsonb WHERE (examples->0->>'ko') = '저의 가방です.';
UPDATE grammar SET examples = '[{"jp": "<ruby>花<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>が<ruby>咲<rp>(</rp><rt>さ</rt><rp>)</rp></ruby>きました。そして<ruby>鳥<rp>(</rp><rt>とり</rt><rp>)</rp></ruby>が<ruby>鳴<rp>(</rp><rt>な</rt><rp>)</rp></ruby>きました。", "ko": "꽃이 피었습니다. 그리고 새가 울었습니다."}, {"jp": "<ruby>宿題<rp>(</rp><rt>しゅくだい</rt><rp>)</rp></ruby>をしました。そしてテレビを<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>ました。", "ko": "숙제를 했습니다. 그리고 TV를 봤습니다."}]'::jsonb WHERE (examples->0->>'ko') = '꽃이 피었습니다. 그리고 새가 울었습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>か<ruby>明後日<rp>(</rp><rt>みょうごにち</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きます。", "ko": "내일이나 모레 갑니다."}, {"jp": "コーヒーか<ruby>紅茶<rp>(</rp><rt>こうちゃ</rt><rp>)</rp></ruby>を<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>みましょう。", "ko": "커피나 홍차를 마십시다."}]'::jsonb WHERE (examples->0->>'ko') = '내일이나 모레 갑니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>の<ruby>家族<rp>(</rp><rt>かぞく</rt><rp>)</rp></ruby>は<ruby>四<rp>(</rp><rt>よん</rt><rp>)</rp></ruby><ruby>人<rp>(</rp><rt>にん</rt><rp>)</rp></ruby>です。", "ko": "저희 가족은 네 명です."}, {"jp": "<ruby>学生<rp>(</rp><rt>がくせい</rt><rp>)</rp></ruby>が<ruby>二<rp>(</rp><rt>に</rt><rp>)</rp></ruby><ruby>十<rp>(</rp><rt>じゅう</rt><rp>)</rp></ruby><ruby>人<rp>(</rp><rt>にん</rt><rp>)</rp></ruby>います。", "ko": "학생이 20명 있습니다."}]'::jsonb WHERE (examples->0->>'ko') = '저희 가족은 네 명です.';
UPDATE grammar SET examples = '[{"jp": "30<ruby>分<rp>(</rp><rt>ふん</rt><rp>)</rp></ruby>くらいかかります。", "ko": "30분 정도 걸립니다."}, {"jp": "リンゴを<ruby>三<rp>(</rp><rt>みっ</rt><rp>)</rp></ruby>つほど<ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>いました。", "ko": "사과를 세 개 정도 샀습니다."}]'::jsonb WHERE (examples->0->>'ko') = '30분 정도 걸립니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>千<rp>(</rp><rt>せん</rt><rp>)</rp></ruby><ruby>円<rp>(</rp><rt>えん</rt><rp>)</rp></ruby>しかありません。", "ko": "천 엔밖에 없습니다."}, {"jp": "<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>人<rp>(</rp><rt>にん</rt><rp>)</rp></ruby>しか<ruby>来<rp>(</rp><rt>き</rt><rp>)</rp></ruby>ませんでした。", "ko": "한 명밖에 안 왔습니다."}]'::jsonb WHERE (examples->0->>'ko') = '천 엔밖에 없습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>家族<rp>(</rp><rt>かぞく</rt><rp>)</rp></ruby>といっしょに<ruby>住<rp>(</rp><rt>す</rt><rp>)</rp></ruby>んでいます。", "ko": "가족과 함께 살고 있습니다."}, {"jp": "<ruby>友達<rp>(</rp><rt>ともだち</rt><rp>)</rp></ruby>といっしょに<ruby>遊<rp>(</rp><rt>あそ</rt><rp>)</rp></ruby>びました。", "ko": "친구와 함께 놀았습니다."}]'::jsonb WHERE (examples->0->>'ko') = '가족과 함께 살고 있습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>早<rp>(</rp><rt>はや</rt><rp>)</rp></ruby>く<ruby>寝<rp>(</rp><rt>ね</rt><rp>)</rp></ruby>たほうがいいです。", "ko": "일찍 자는 편이 좋습니다."}, {"jp": "<ruby>病院<rp>(</rp><rt>びょういん</rt><rp>)</rp></ruby>へ<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ったほうがいいです。", "ko": "병원에 가는 편이 좋습니다."}]'::jsonb WHERE (examples->0->>'ko') = '일찍 자는 편이 좋습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>友達<rp>(</rp><rt>ともだち</rt><rp>)</rp></ruby>に<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>を<ruby>教<rp>(</rp><rt>おし</rt><rp>)</rp></ruby>えてあげました。", "ko": "친구에게 일본어를 가르쳐 주었습니다."}, {"jp": "<ruby>母<rp>(</rp><rt>はは</rt><rp>)</rp></ruby>に<ruby>本<rp>(</rp><rt>ほん</rt><rp>)</rp></ruby>を<ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>ってもらいました。", "ko": "어머니가 책을 사 주셨습니다."}]'::jsonb WHERE (examples->0->>'ko') = '친구에게 일본어를 가르쳐 주었습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>子供<rp>(</rp><rt>こども</rt><rp>)</rp></ruby>を<ruby>遊<rp>(</rp><rt>あそ</rt><rp>)</rp></ruby>ばせます。", "ko": "아이를 놀게 합니다."}, {"jp": "<ruby>弟<rp>(</rp><rt>おとうと</rt><rp>)</rp></ruby>に<ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>い<ruby>物<rp>(</rp><rt>もの</rt><rp>)</rp></ruby>をさせます。", "ko": "남동생에게 쇼핑을 시킵니다."}]'::jsonb WHERE (examples->0->>'ko') = '아이를 놀게 합니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby><ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>く<ruby>予定<rp>(</rp><rt>よてい</rt><rp>)</rp></ruby>です。", "ko": "내일 갈 예정です."}, {"jp": "<ruby>出張<rp>(</rp><rt>しゅっちょう</rt><rp>)</rp></ruby>の<ruby>予定<rp>(</rp><rt>よてい</rt><rp>)</rp></ruby>です。", "ko": "출장 예정です."}]'::jsonb WHERE (examples->0->>'ko') = '내일 갈 예정です.';
UPDATE grammar SET examples = '[{"jp": "<ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>しに<ruby>図書館<rp>(</rp><rt>としょかん</rt><rp>)</rp></ruby>へ<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きます。", "ko": "공부하러 도서관에 갑니다."}, {"jp": "ご<ruby>飯<rp>(</rp><rt>はん</rt><rp>)</rp></ruby>を<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べにレストランへ<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きます。", "ko": "밥을 먹으러 레스토랑에 갑니다."}]'::jsonb WHERE (examples->0->>'ko') = '공부하러 도서관에 갑니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>に<ruby>褒<rp>(</rp><rt>ほ</rt><rp>)</rp></ruby>められました。", "ko": "선생님께 칭찬받았습니다."}, {"jp": "<ruby>泥棒<rp>(</rp><rt>どろぼう</rt><rp>)</rp></ruby>に<ruby>財布<rp>(</rp><rt>さいふ</rt><rp>)</rp></ruby>を<ruby>盗<rp>(</rp><rt>ぬす</rt><rp>)</rp></ruby>まれました。", "ko": "도둑에게 지갑을 도둑맞았습니다."}]'::jsonb WHERE (examples->0->>'ko') = '선생님께 칭찬받았습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>がお<ruby>帰<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>りになります。", "ko": "선생님이 귀가하십니다."}, {"jp": "<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>をお<ruby>読<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>みになりますか?", "ko": "무엇을 읽으십니까?"}]'::jsonb WHERE (examples->0->>'ko') = '선생님이 귀가하십니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>安<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>かったら<ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>います。", "ko": "싸면 사겠습니다."}, {"jp": "<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby>へ<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ったら<ruby>連絡<rp>(</rp><rt>れんらく</rt><rp>)</rp></ruby>します。", "ko": "일본에 가면 연락하겠습니다."}]'::jsonb WHERE (examples->0->>'ko') = '싸면 사겠습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>宿題<rp>(</rp><rt>しゅくだい</rt><rp>)</rp></ruby>をして<ruby>寝<rp>(</rp><rt>ね</rt><rp>)</rp></ruby>ます。", "ko": "숙제를 하고 잡니다."}, {"jp": "この<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>は<ruby>広<rp>(</rp><rt>ひろ</rt><rp>)</rp></ruby>くて<ruby>綺麗<rp>(</rp><rt>きれい</rt><rp>)</rp></ruby>です。", "ko": "이 방은 넓고 깨끗합니다."}]'::jsonb WHERE (examples->0->>'ko') = '숙제를 하고 잡니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>は<ruby>大変<rp>(</rp><rt>たいへん</rt><rp>)</rp></ruby>ですが、<ruby>楽<rp>(</rp><rt>たの</rt><rp>)</rp></ruby>しいです。", "ko": "공부는 힘들지만 즐겁습니다."}, {"jp": "<ruby>失礼<rp>(</rp><rt>しつれい</rt><rp>)</rp></ruby>ですが、お<ruby>名前<rp>(</rp><rt>なまえ</rt><rp>)</rp></ruby>は?", "ko": "실례지만 성함이 어떻게 되세요?"}]'::jsonb WHERE (examples->0->>'ko') = '공부는 힘들지만 즐겁습니다.';
UPDATE grammar SET examples = '[{"jp": "このペンは<ruby>書<rp>(</rp><rt>か</rt><rp>)</rp></ruby>きやすいです。", "ko": "이 펜은 쓰기 쉽습니다."}, {"jp": "この<ruby>本<rp>(</rp><rt>ほん</rt><rp>)</rp></ruby>は<ruby>読<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>みやすいです。", "ko": "이 책은 읽기 쉽습니다."}]'::jsonb WHERE (examples->0->>'ko') = '이 펜은 쓰기 쉽습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>雨<rp>(</rp><rt>う</rt><rp>)</rp></ruby>が<ruby>降<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>るようです。", "ko": "비가 올 것 같습니다."}, {"jp": "<ruby>雪<rp>(</rp><rt>せつ</rt><rp>)</rp></ruby>のようです。", "ko": "눈인 것 같습니다."}]'::jsonb WHERE (examples->0->>'ko') = '비가 올 것 같습니다.';
UPDATE grammar SET examples = '[{"jp": "ご<ruby>飯<rp>(</rp><rt>はん</rt><rp>)</rp></ruby>を<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べる<ruby>時<rp>(</rp><rt>とき</rt><rp>)</rp></ruby>、「いただきます」と<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>います。", "ko": "밥을 먹을 때 \"잘 먹겠습니다\"라고 말합니다."}, {"jp": "<ruby>子供<rp>(</rp><rt>こども</rt><rp>)</rp></ruby>の<ruby>時<rp>(</rp><rt>とき</rt><rp>)</rp></ruby>、よく<ruby>泳<rp>(</rp><rt>およ</rt><rp>)</rp></ruby>ぎました。", "ko": "어릴 때 자주 수영했습니다."}]'::jsonb WHERE (examples->0->>'ko') = '밥을 먹을 때 "잘 먹겠습니다"라고 말합니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>机<rp>(</rp><rt>つくえ</rt><rp>)</rp></ruby>の<ruby>上<rp>(</rp><rt>うえ</rt><rp>)</rp></ruby>にあります。", "ko": "책상 위에 있습니다."}, {"jp": "カバンの<ruby>中<rp>(</rp><rt>なか</rt><rp>)</rp></ruby>にあります。", "ko": "가방 안에 있습니다."}]'::jsonb WHERE (examples->0->>'ko') = '책상 위에 있습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>忘<rp>(</rp><rt>わす</rt><rp>)</rp></ruby>れないでください。", "ko": "잊지 마세요."}, {"jp": "<ruby>入<rp>(</rp><rt>はい</rt><rp>)</rp></ruby>らないでください。", "ko": "들어가지 마세요."}]'::jsonb WHERE (examples->0->>'ko') = '잊지 마세요.';
UPDATE grammar SET examples = '[{"jp": "<ruby>友達<rp>(</rp><rt>ともだち</rt><rp>)</rp></ruby>に<ruby>本<rp>(</rp><rt>ほん</rt><rp>)</rp></ruby>をあげました。", "ko": "친구에게 책을 주었습니다."}, {"jp": "<ruby>母<rp>(</rp><rt>はは</rt><rp>)</rp></ruby>に<ruby>時計<rp>(</rp><rt>とけい</rt><rp>)</rp></ruby>をもらいました。", "ko": "어머니께 시계를 받았습니다."}]'::jsonb WHERE (examples->0->>'ko') = '친구에게 책을 주었습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby><ruby>何<rp>(</rp><rt>なん</rt><rp>)</rp></ruby><ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>ですか?", "ko": "지금 몇 시ですか?"}, {"jp": "<ruby>九<rp>(</rp><rt>きゅう</rt><rp>)</rp></ruby><ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>十<rp>(</rp><rt>じゅう</rt><rp>)</rp></ruby><ruby>五<rp>(</rp><rt>ご</rt><rp>)</rp></ruby><ruby>分<rp>(</rp><rt>ふん</rt><rp>)</rp></ruby>です。", "ko": "9시 15분です."}]'::jsonb WHERE (examples->0->>'ko') = '지금 몇 시ですか?';
UPDATE grammar SET examples = '[{"jp": "<ruby>夏<rp>(</rp><rt>なつ</rt><rp>)</rp></ruby>より<ruby>冬<rp>(</rp><rt>ふゆ</rt><rp>)</rp></ruby>のほうが<ruby>好<rp>(</rp><rt>す</rt><rp>)</rp></ruby>きです。", "ko": "여름보다 겨울을 더 좋아합니다."}, {"jp": "コーヒーのほうが<ruby>安<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>いです。", "ko": "커피 쪽이 더 쌉니다."}]'::jsonb WHERE (examples->0->>'ko') = '여름보다 겨울을 더 좋아합니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>水<rp>(</rp><rt>すい</rt><rp>)</rp></ruby>だけ<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>みます。", "ko": "물만 마십니다."}, {"jp": "<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>だけ<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きませんでした。", "ko": "저만 가지 않았습니다."}]'::jsonb WHERE (examples->0->>'ko') = '물만 마십니다.';
UPDATE grammar SET examples = '[{"jp": "これは<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>で<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>といいますか?", "ko": "이것은 일본어로 무엇이라고 합니까?"}, {"jp": "あの<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>は<ruby>田中<rp>(</rp><rt>たなか</rt><rp>)</rp></ruby>さんといいます。", "ko": "저 사람은 다나카 씨라고 합니다."}]'::jsonb WHERE (examples->0->>'ko') = '이것은 일본어로 무엇이라고 합니까?';
UPDATE grammar SET examples = '[{"jp": "<ruby>猫<rp>(</rp><rt>ねこ</rt><rp>)</rp></ruby>も<ruby>犬<rp>(</rp><rt>いぬ</rt><rp>)</rp></ruby>もいます。", "ko": "고양이도 개도 있습니다."}, {"jp": "お<ruby>茶<rp>(</rp><rt>ちゃ</rt><rp>)</rp></ruby>も<ruby>水<rp>(</rp><rt>みず</rt><rp>)</rp></ruby>も<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>みました。", "ko": "차도 물도 마셨습니다."}]'::jsonb WHERE (examples->0->>'ko') = '고양이도 개도 있습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>日<rp>(</rp><rt>にち</rt><rp>)</rp></ruby>に<ruby>三<rp>(</rp><rt>さん</rt><rp>)</rp></ruby><ruby>回<rp>(</rp><rt>かい</rt><rp>)</rp></ruby><ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べます。", "ko": "하루에 세 번 먹습니다."}, {"jp": "<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby>に<ruby>二<rp>(</rp><rt>に</rt><rp>)</rp></ruby><ruby>回<rp>(</rp><rt>かい</rt><rp>)</rp></ruby><ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きました。", "ko": "일본에 두 번 갔습니다."}]'::jsonb WHERE (examples->0->>'ko') = '하루에 세 번 먹습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>雨<rp>(</rp><rt>う</rt><rp>)</rp></ruby>が<ruby>降<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>り<ruby>始<rp>(</rp><rt>はじ</rt><rp>)</rp></ruby>めました。", "ko": "비가 내리기 시작했습니다."}, {"jp": "<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べ<ruby>始<rp>(</rp><rt>はじ</rt><rp>)</rp></ruby>めましょう。", "ko": "먹기 시작합시다."}]'::jsonb WHERE (examples->0->>'ko') = '비가 내리기 시작했습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>今日<rp>(</rp><rt>きょう</rt><rp>)</rp></ruby>は<ruby>一月<rp>(</rp><rt>いちがつ</rt><rp>)</rp></ruby><ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>日<rp>(</rp><rt>にち</rt><rp>)</rp></ruby>です。", "ko": "오늘은 1월 1일です."}, {"jp": "<ruby>誕生<rp>(</rp><rt>たんじょう</rt><rp>)</rp></ruby><ruby>日<rp>(</rp><rt>び</rt><rp>)</rp></ruby>は<ruby>五月<rp>(</rp><rt>ごがつ</rt><rp>)</rp></ruby><ruby>三<rp>(</rp><rt>さん</rt><rp>)</rp></ruby><ruby>日<rp>(</rp><rt>にち</rt><rp>)</rp></ruby>です。", "ko": "생일은 5월 3일です."}]'::jsonb WHERE (examples->0->>'ko') = '오늘은 1월 1일です.';
UPDATE grammar SET examples = '[{"jp": "<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>は「<ruby>宿題<rp>(</rp><rt>しゅくだい</rt><rp>)</rp></ruby>です」と<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>いました。", "ko": "선생님은 「숙제です」라고 말했습니다."}, {"jp": "<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>は「<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きます」と<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>いました。", "ko": "그는 「갑니다」라고 말했습니다."}]'::jsonb WHERE (examples->0->>'ko') = '선생님은 「숙제です」라고 말했습니다.';
UPDATE grammar SET examples = '[{"jp": "この<ruby>漢字<rp>(</rp><rt>かんじ</rt><rp>)</rp></ruby>は<ruby>覚<rp>(</rp><rt>おぼ</rt><rp>)</rp></ruby>えにくいです。", "ko": "이 한자는 외우기 어렵습니다."}, {"jp": "この<ruby>肉<rp>(</rp><rt>にく</rt><rp>)</rp></ruby>は<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べにくいです。", "ko": "이 고기는 먹기 어렵습니다."}]'::jsonb WHERE (examples->0->>'ko') = '이 한자는 외우기 어렵습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>は<ruby>学生<rp>(</rp><rt>がくせい</rt><rp>)</rp></ruby>です。", "ko": "저는 학생です."}, {"jp": "これは<ruby>本<rp>(</rp><rt>ほん</rt><rp>)</rp></ruby>です。", "ko": "이것은 책です."}]'::jsonb WHERE (examples->0->>'ko') = '저는 학생です.';
UPDATE grammar SET examples = '[{"jp": "<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>は<ruby>来<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>なくてもいいです。", "ko": "내일은 오지 않아도 됩니다."}, {"jp": "<ruby>急<rp>(</rp><rt>いそ</rt><rp>)</rp></ruby>がなくてもいいです。", "ko": "서두르지 않아도 됩니다."}]'::jsonb WHERE (examples->0->>'ko') = '내일은 오지 않아도 됩니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>雨<rp>(</rp><rt>う</rt><rp>)</rp></ruby>が<ruby>降<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>ったので<ruby>遅<rp>(</rp><rt>おく</rt><rp>)</rp></ruby>れました。", "ko": "비가 와서 늦었습니다."}, {"jp": "お<ruby>腹<rp>(</rp><rt>なか</rt><rp>)</rp></ruby>が<ruby>空<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>いたので、<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>か<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べたいです。", "ko": "배가 고파서 무언가 먹고 싶습니다."}]'::jsonb WHERE (examples->0->>'ko') = '비가 와서 늦었습니다.';
UPDATE grammar SET examples = '[{"jp": "もし<ruby>雨<rp>(</rp><rt>あめ</rt><rp>)</rp></ruby>が<ruby>降<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>ったら<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きません。", "ko": "만약 비가 오면 가지 않습니다."}, {"jp": "もしかしたら<ruby>遅<rp>(</rp><rt>おく</rt><rp>)</rp></ruby>れるかもしれません。", "ko": "혹시 늦을지도 모릅니다."}]'::jsonb WHERE (examples->0->>'ko') = '만약 비가 오면 가지 않습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>学校<rp>(</rp><rt>がっこう</rt><rp>)</rp></ruby>へ<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きます。", "ko": "학교에 갑니다."}, {"jp": "<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby>へ<ruby>来<rp>(</rp><rt>き</rt><rp>)</rp></ruby>ました。", "ko": "일본에 왔습니다."}]'::jsonb WHERE (examples->0->>'ko') = '학교에 갑니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>駅<rp>(</rp><rt>えき</rt><rp>)</rp></ruby>までどうやって<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きますか?", "ko": "역까지 어떻게 갑니까?"}, {"jp": "これはどうやって<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べますか?", "ko": "이것은 어떻게 먹습니까?"}]'::jsonb WHERE (examples->0->>'ko') = '역까지 어떻게 갑니까?';
UPDATE grammar SET examples = '[{"jp": "<ruby>試験<rp>(</rp><rt>しけん</rt><rp>)</rp></ruby>はいつですか?", "ko": "시험은 언제ですか?"}, {"jp": "どのくらいかかりますか?", "ko": "얼마나 걸립니까?"}]'::jsonb WHERE (examples->0->>'ko') = '시험은 언제ですか?';
UPDATE grammar SET examples = '[{"jp": "これは<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>ですか?", "ko": "이것은 무엇ですか?"}, {"jp": "<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>を<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べるましたか?", "ko": "무엇을 먹었습니까?"}]'::jsonb WHERE (examples->0->>'ko') = '이것은 무엇ですか?';
UPDATE grammar SET examples = '[{"jp": "<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>は<ruby>雨<rp>(</rp><rt>あめ</rt><rp>)</rp></ruby>でしょう。", "ko": "내일은 비가 오겠지요."}, {"jp": "これ、<ruby>美味<rp>(</rp><rt>おい</rt><rp>)</rp></ruby>しいでしょう?", "ko": "이거 맛있죠?"}]'::jsonb WHERE (examples->0->>'ko') = '내일은 비가 오겠지요.';
UPDATE grammar SET examples = '[{"jp": "<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>は<ruby>暇<rp>(</rp><rt>ひま</rt><rp>)</rp></ruby>かもしれません。", "ko": "내일은 한가할지도 모릅니다."}, {"jp": "<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>は<ruby>来<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>ないかもしれません。", "ko": "그는 오지 않을지도 모릅니다."}]'::jsonb WHERE (examples->0->>'ko') = '내일은 한가할지도 모릅니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>本屋<rp>(</rp><rt>ほんや</rt><rp>)</rp></ruby>はあそこにあります。", "ko": "서점은 저기에 있습니다."}, {"jp": "<ruby>猫<rp>(</rp><rt>ねこ</rt><rp>)</rp></ruby>は<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>にいます。", "ko": "고양이는 방에 있습니다."}]'::jsonb WHERE (examples->0->>'ko') = '서점은 저기에 있습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>は<ruby>難<rp>(</rp><rt>むずか</rt><rp>)</rp></ruby>しいと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>います。", "ko": "일본어는 어렵다고 생각합니다."}, {"jp": "<ruby>友達<rp>(</rp><rt>ともだち</rt><rp>)</rp></ruby>が<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>ると<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>います。", "ko": "친구가 올 것이라고 생각합니다."}]'::jsonb WHERE (examples->0->>'ko') = '일본어는 어렵다고 생각합니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>が<ruby>上手<rp>(</rp><rt>じょうず</rt><rp>)</rp></ruby>ですね。", "ko": "일본어를 잘하시네요."}, {"jp": "<ruby>料理<rp>(</rp><rt>りょうり</rt><rp>)</rp></ruby>が<ruby>上手<rp>(</rp><rt>じょうず</rt><rp>)</rp></ruby>です。", "ko": "요리를 잘합니다."}]'::jsonb WHERE (examples->0->>'ko') = '일본어를 잘하시네요.';
UPDATE grammar SET examples = '[{"jp": "<ruby>歌<rp>(</rp><rt>か</rt><rp>)</rp></ruby>が<ruby>下手<rp>(</rp><rt>へた</rt><rp>)</rp></ruby>です。", "ko": "노래를 못합니다."}, {"jp": "テニスが<ruby>下手<rp>(</rp><rt>へた</rt><rp>)</rp></ruby>です。", "ko": "테니스를 못합니다."}]'::jsonb WHERE (examples->0->>'ko') = '노래를 못합니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>図書館<rp>(</rp><rt>としょかん</rt><rp>)</rp></ruby>で<ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>します。", "ko": "도서관에서 공부합니다."}, {"jp": "バスで<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きます。", "ko": "버스로 갑니다."}]'::jsonb WHERE (examples->0->>'ko') = '도서관에서 공부합니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>学校<rp>(</rp><rt>がっこう</rt><rp>)</rp></ruby>へ<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>かなければなりません。", "ko": "학교에 가야 합니다."}, {"jp": "<ruby>宿題<rp>(</rp><rt>しゅくだい</rt><rp>)</rp></ruby>をしなければなりません。", "ko": "숙제를 해야 합니다."}]'::jsonb WHERE (examples->0->>'ko') = '학교에 가야 합니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>休<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>みはテレビを<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>たり、<ruby>本<rp>(</rp><rt>ほん</rt><rp>)</rp></ruby>を<ruby>読<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>んだりします。", "ko": "주말에는 TV를 보거나 책을 읽거나 합니다."}, {"jp": "<ruby>掃除<rp>(</rp><rt>そうじ</rt><rp>)</rp></ruby>したり、<ruby>洗濯<rp>(</rp><rt>せんたく</rt><rp>)</rp></ruby>したりしました。", "ko": "청소를 하거나 빨래를 하거나 했습니다."}]'::jsonb WHERE (examples->0->>'ko') = '주말에는 TV를 보거나 책을 읽거나 합니다.';
UPDATE grammar SET examples = '[{"jp": "このケーキは<ruby>美味<rp>(</rp><rt>おい</rt><rp>)</rp></ruby>しそうですね。", "ko": "이 케이크는 맛있어 보이네요."}, {"jp": "<ruby>雨<rp>(</rp><rt>う</rt><rp>)</rp></ruby>が<ruby>降<rp>(</rp><rt>お</rt><rp>)</rp></ruby>りそうですね。", "ko": "비가 올 것 같네요."}]'::jsonb WHERE (examples->0->>'ko') = '이 케이크는 맛있어 보이네요.';
UPDATE grammar SET examples = '[{"jp": "<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>人<rp>(</rp><rt>にん</rt><rp>)</rp></ruby>で<ruby>学校<rp>(</rp><rt>がっこう</rt><rp>)</rp></ruby>へ<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きます。", "ko": "혼자서 학교에 갑니다."}, {"jp": "<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>人<rp>(</rp><rt>にん</rt><rp>)</rp></ruby>で<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べます。", "ko": "혼자서 먹습니다."}]'::jsonb WHERE (examples->0->>'ko') = '혼자서 학교에 갑니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>水<rp>(</rp><rt>すい</rt><rp>)</rp></ruby>を<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>みます。", "ko": "물을 마십니다."}, {"jp": "ご<ruby>飯<rp>(</rp><rt>はん</rt><rp>)</rp></ruby>を<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べます。", "ko": "밥을 먹습니다."}]'::jsonb WHERE (examples->0->>'ko') = '물을 마십니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>는 <ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>年生<rp>(</rp><rt>ねんせい</rt><rp>)</rp></ruby>です。", "ko": "저는 1학년です."}, {"jp": "<ruby>弟<rp>(</rp><rt>おとうと</rt><rp>)</rp></ruby>는 <ruby>五<rp>(</rp><rt>ご</rt><rp>)</rp></ruby><ruby>年生<rp>(</rp><rt>ねんせい</rt><rp>)</rp></ruby>です。", "ko": "동생은 5학년です."}]'::jsonb WHERE (examples->0->>'ko') = '저는 1학년です.';
UPDATE grammar SET examples = '[{"jp": "<ruby>友達<rp>(</rp><rt>ともだち</rt><rp>)</rp></ruby>と<ruby>会<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>います。", "ko": "친구와 만듭니다."}, {"jp": "パンとミルク。", "ko": "빵과 우유."}]'::jsonb WHERE (examples->0->>'ko') = '친구와 만듭니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>も<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きます。", "ko": "저도 갑니다."}, {"jp": "これも<ruby>美味<rp>(</rp><rt>おい</rt><rp>)</rp></ruby>しいです。", "ko": "이것도 맛있습니다."}]'::jsonb WHERE (examples->0->>'ko') = '저도 갑니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>日曜日<rp>(</rp><rt>にちようび</rt><rp>)</rp></ruby>に<ruby>会<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>います。", "ko": "일요일에 만납니다."}, {"jp": "<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>にあります。", "ko": "방에 있습니다."}]'::jsonb WHERE (examples->0->>'ko') = '일요일에 만납니다.';
UPDATE grammar SET examples = '[{"jp": "とても<ruby>綺麗<rp>(</rp><rt>きれい</rt><rp>)</rp></ruby>ですね。", "ko": "매우 예쁘네요."}, {"jp": "とても<ruby>寒<rp>(</rp><rt>さむ</rt><rp>)</rp></ruby>いです。", "ko": "매우 춥습니다."}]'::jsonb WHERE (examples->0->>'ko') = '매우 예쁘네요.';
UPDATE grammar SET examples = '[{"jp": "リンゴを<ruby>三<rp>(</rp><rt>みっ</rt><rp>)</rp></ruby>つ<ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>いました。", "ko": "사과를 세 개 샀습니다."}, {"jp": "<ruby>椅子<rp>(</rp><rt>いす</rt><rp>)</rp></ruby>が<ruby>一<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>つあります。", "ko": "의자가 한 개 있습니다."}]'::jsonb WHERE (examples->0->>'ko') = '사과를 세 개 샀습니다.';
UPDATE grammar SET examples = '[{"jp": "お<ruby>荷物<rp>(</rp><rt>にもつ</rt><rp>)</rp></ruby>をお<ruby>持<rp>(</rp><rt>も</rt><rp>)</rp></ruby>ちします。", "ko": "짐을 들어 드리겠습니다."}, {"jp": "お<ruby>待<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>ちいたしました。", "ko": "기다렸습니다 (겸양)."}]'::jsonb WHERE (examples->0->>'ko') = '짐을 들어 드리겠습니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>少<rp>(</rp><rt>すこ</rt><rp>)</rp></ruby>し<ruby>疲<rp>(</rp><rt>つか</rt><rp>)</rp></ruby>れました。", "ko": "조금 피곤합니다."}, {"jp": "ちょっと<ruby>待<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>ってください。", "ko": "잠시 기다려 주세요."}]'::jsonb WHERE (examples->0->>'ko') = '조금 피곤합니다.';
UPDATE grammar SET examples = '[{"jp": "<ruby>座<rp>(</rp><rt>すわ</rt><rp>)</rp></ruby>ってください。", "ko": "앉아 주세요."}, {"jp": "<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>せてください。", "ko": "보여주세요."}]'::jsonb WHERE (examples->0->>'ko') = '앉아 주세요.';
